/**
 * Process-global W3C `traceparent` propagator. Inbound HTTP extracts
 * trace context only. BDK does not read or write the `baggage` header.
 * Turn tags stay in this process.
 */
import { propagation } from "@opentelemetry/api";
import { W3CTraceContextPropagator } from "@opentelemetry/core";
let installed = false;
export function ensureW3cPropagator() {
    if (installed) {
        return;
    }
    propagation.setGlobalPropagator(new W3CTraceContextPropagator());
    installed = true;
}
